'use server'

import { updateTag } from 'next/cache'
import { addPost } from './posts'

export async function createPost(formData: FormData): Promise<void> {
  const title = formData.get('title')
  const body = formData.get('body')

  if (typeof title !== 'string' || typeof body !== 'string') return

  const trimmedTitle = title.trim()
  const trimmedBody = body.trim()

  if (!trimmedTitle || trimmedTitle.length > 120 || trimmedBody.length > 5000) {
    return
  }

  addPost(trimmedTitle, trimmedBody)

  // Expire the tagged cache immediately so the next read waits for fresh data.
  updateTag('posts')
}
import 'server-only'

import { unstable_cache } from 'next/cache'

export type Post = {
  id: string
  title: string
  body: string
  createdAt: string
}

type PostsGlobal = typeof globalThis & {
